user_prompt_template:
TUTORIAL REQUEST: {tutorial_request}
SKILL LEVEL: {skill_level}
OUTPUT STYLE: {output_style}
TUTORIAL TYPE: {tutorial_type}
TUTORIAL DEPTH: {tutorial_depth}
