  "system_objective": "Concrete end-state: what the learner will build or be able to do",
  "time_horizon": "Estimated time budget or depth expectation",
  "control_domains": [
    {{
      "id": "module-01",
      "name": "Specific module title",
      "purpose": "What this module teaches/builds",
      "scope_in": ["In-scope tasks"],
      "scope_out": ["Out-of-scope tasks"],
      "primary_outputs": ["Deliverables produced in this module"]
    }}
  ],
  "key_roles": [
    {{
      "role": "Learner or collaborator role",
      "responsibility": "What this role must do",
      "authority_level": "decision-maker | advisor | executor | observer"
    }}
  ],
  "critical_milestones": [
    {{
      "milestone": "Checkpoint title",
      "description": "What must be true at this checkpoint",
      "sequence": 1
    }}
  ],
  "success_criteria": ["Verifiable completion criteria"],
  "failure_modes": ["Likely mistakes or blockers"],
  "operating_constraints": ["Constraints from tools/time/platform/security/cost"]
